// Synthesized instruments for every instrument name the backend can send
// (INSTRUMENTS in backend/app/mapping/music.py). Everything is generated by Tone.js
// synthesizers, so there are no audio sample files to download.

import * as Tone from "tone";

/** Something that can play a step of a pattern. */
export interface Instrument {
  /** Where the sound comes out; the player connects this to the mixer. */
  readonly output: Tone.ToneAudioNode;
  /**
   * Play the notes listed for one step ("C4", "E4", ... or drum names for the drum kit).
   * `time` is an exact moment on the audio clock, given by the transport's callback;
   * scheduling against it (rather than "now") is what keeps everything in time.
   */
  play(notes: string[], duration: Tone.Unit.Time, time: number): void;
  dispose(): void;
}

/** For polyphonic synths, which can play whole chords. */
function polyphonic(synth: Tone.PolySynth, volumeDb: number): Instrument {
  synth.volume.value = volumeDb;
  return {
    output: synth,
    play: (notes, duration, time) => synth.triggerAttackRelease(notes, duration, time),
    dispose: () => synth.dispose(),
  };
}

/** For single-voice synths: melody, bass, and arpeggio steps only ever hold one note. */
function monophonic(
  synth: Tone.MonoSynth | Tone.FMSynth | Tone.PluckSynth,
  volumeDb: number,
): Instrument {
  synth.volume.value = volumeDb;
  return {
    output: synth,
    play: (notes, duration, time) => {
      const [note] = notes;
      if (note !== undefined) {
        synth.triggerAttackRelease(note, duration, time);
      }
    },
    dispose: () => synth.dispose(),
  };
}

/** Run an instrument through a low-pass filter to soften harsh, buzzy oscillators. */
function softened(instrument: Instrument, cutoffHz: number): Instrument {
  const filter = new Tone.Filter(cutoffHz, "lowpass");
  instrument.output.connect(filter);
  return {
    output: filter,
    play: instrument.play,
    dispose: () => {
      instrument.dispose();
      filter.dispose();
    },
  };
}

/** Kick, snare, and hi-hat, triggered by the names "kick", "snare", and "hat". */
function drumKit(): Instrument {
  const output = new Tone.Gain(1);
  // A kick is a sine wave whose pitch drops fast; MembraneSynth does exactly that.
  const kick = new Tone.MembraneSynth({
    pitchDecay: 0.04,
    octaves: 6,
    envelope: { attack: 0.001, decay: 0.35, sustain: 0, release: 0.1 },
  }).connect(output);
  kick.volume.value = -6;
  // A snare is mostly a short burst of noise; the high-pass filter takes away the rumble.
  const snareFilter = new Tone.Filter(1500, "highpass").connect(output);
  const snare = new Tone.NoiseSynth({
    noise: { type: "white" },
    envelope: { attack: 0.001, decay: 0.16, sustain: 0, release: 0.05 },
  }).connect(snareFilter);
  snare.volume.value = -14;
  // A hi-hat is a very short, bright metallic tick.
  const hat = new Tone.MetalSynth({
    envelope: { attack: 0.001, decay: 0.05, release: 0.01 },
    harmonicity: 5.1,
    modulationIndex: 32,
    resonance: 4000,
    octaves: 1.5,
  }).connect(output);
  hat.volume.value = -30;

  return {
    output,
    play: (hits, _duration, time) => {
      for (const hit of hits) {
        if (hit === "kick") kick.triggerAttackRelease("C1", "8n", time);
        else if (hit === "snare") snare.triggerAttackRelease("16n", time);
        else if (hit === "hat") hat.triggerAttackRelease(300, "32n", time);
      }
    },
    dispose: () => {
      for (const node of [kick, snare, snareFilter, hat, output]) node.dispose();
    },
  };
}

// Volumes are trims (in decibels) that roughly balance the presets against each other; the
// track's own volume from the backend is applied on top by the player.
const PRESETS: Record<string, () => Instrument> = {
  // Melody
  piano: () =>
    polyphonic(
      new Tone.PolySynth(Tone.FMSynth, {
        harmonicity: 2,
        modulationIndex: 1.5,
        envelope: { attack: 0.005, decay: 0.8, sustain: 0.2, release: 1.2 },
        modulationEnvelope: { attack: 0.005, decay: 0.5, sustain: 0.1, release: 0.8 },
      }),
      -12,
    ),
  pluck: () =>
    monophonic(new Tone.PluckSynth({ attackNoise: 1, dampening: 3500, resonance: 0.92 }), -4),
  bell: () =>
    polyphonic(
      new Tone.PolySynth(Tone.FMSynth, {
        harmonicity: 3.01,
        modulationIndex: 12,
        envelope: { attack: 0.001, decay: 1.4, sustain: 0, release: 1.4 },
        modulationEnvelope: { attack: 0.001, decay: 0.8, sustain: 0, release: 0.5 },
      }),
      -18,
    ),
  lead: () =>
    monophonic(
      new Tone.MonoSynth({
        oscillator: { type: "sawtooth" },
        filter: { Q: 2, type: "lowpass", rolloff: -24 },
        envelope: { attack: 0.01, decay: 0.2, sustain: 0.4, release: 0.4 },
        filterEnvelope: { attack: 0.01, decay: 0.3, sustain: 0.3, release: 0.5, baseFrequency: 400, octaves: 3 },
      }),
      -16,
    ),

  // Bass
  "synth-bass": () =>
    monophonic(
      new Tone.MonoSynth({
        oscillator: { type: "square" },
        filter: { Q: 1, type: "lowpass" },
        envelope: { attack: 0.005, decay: 0.3, sustain: 0.4, release: 0.3 },
        filterEnvelope: { attack: 0.005, decay: 0.2, sustain: 0.2, release: 0.3, baseFrequency: 120, octaves: 2.5 },
      }),
      -10,
    ),
  "fm-bass": () =>
    monophonic(
      new Tone.FMSynth({
        harmonicity: 1,
        modulationIndex: 4,
        envelope: { attack: 0.005, decay: 0.3, sustain: 0.5, release: 0.4 },
        modulationEnvelope: { attack: 0.005, decay: 0.2, sustain: 0.2, release: 0.3 },
      }),
      -8,
    ),

  // Chords
  pad: () =>
    softened(
      polyphonic(
        new Tone.PolySynth(Tone.Synth, {
          oscillator: { type: "fatsawtooth", count: 3, spread: 30 },
          envelope: { attack: 0.6, decay: 0.5, sustain: 0.8, release: 2 },
        }),
        -24,
      ),
      1200,
    ),
  strings: () =>
    softened(
      polyphonic(
        new Tone.PolySynth(Tone.AMSynth, {
          harmonicity: 1.5,
          oscillator: { type: "sawtooth" },
          envelope: { attack: 0.4, decay: 0.3, sustain: 0.8, release: 1.5 },
        }),
        -22,
      ),
      2000,
    ),
  organ: () =>
    polyphonic(
      new Tone.PolySynth(Tone.Synth, {
        // A fundamental plus quieter overtones: the drawbar sound of an organ.
        oscillator: { type: "custom", partials: [1, 0.5, 0.33, 0.25] },
        envelope: { attack: 0.02, decay: 0.1, sustain: 0.9, release: 0.3 },
      }),
      -20,
    ),

  // Arpeggio
  marimba: () =>
    polyphonic(
      new Tone.PolySynth(Tone.FMSynth, {
        harmonicity: 4,
        modulationIndex: 2.5,
        envelope: { attack: 0.001, decay: 0.5, sustain: 0, release: 0.4 },
        modulationEnvelope: { attack: 0.001, decay: 0.15, sustain: 0, release: 0.1 },
      }),
      -10,
    ),

  // Drums
  "drum-kit": drumKit,
};

/** A fresh instrument for a backend instrument name (unknown names fall back to piano). */
export function createInstrument(name: string): Instrument {
  return (PRESETS[name] ?? PRESETS.piano)();
}
